    /// assert_eq!(triple_rotator.basis_blades(), Vee::triple_rotator().basis_blades());
    /// format_eq!(triple_rotator, [
    ///     "+v͔v͕-α͔α͕-β͔β͕-γ͔γ͕-δ͔δ͕-ε͔ε͕-ζ͔ζ͕-η͔η͕-θ͔θ͕-ι͔ι͕-κ͔κ͕-λ͔λ͕-μ͔μ͕-ν͔ν͕-ξ͔ξ͕-ο͔ο͕",
