    ///     "+(+ẋ͔ẏ͕-ẋ͕ẏ͔)e12",
    ///     "+(+ẋ͔ż͕-ẋ͕ż͔)e13",
    ///     "+(+ẋ͔ð͕̇-ẋ͕ð͔̇)e14",
    ///     "+(+ẋ͔ø͕̇-ẋ͕ø͔̇)e15",
    ///     "+(+ẋ͔þ͕̇-ẋ͕þ͔̇)e16",
    ///     "+(+ẏ͔ż͕-ẏ͕ż͔)e23",
    ///     "+(+ẏ͔ð͕̇-ẏ͕ð͔̇)e24",
